// Gmail queries per newsletter source.
// newer_than:7d (was 2d): the ingest POST used to 500 on dead pooled DB
// connections, n8n aborted the run, and a 2-day window then moved past every
// skipped issue permanently — 137 of 200 issues in 100 days were lost that way.
// A 7-day window re-offers anything a failed run missed; newsletters.email_id is
// unique so re-offering is idempotent.
// in:anywhere: Jordan West and DTC Daily issues land in TRASH, and the default
// query scope silently skips spam/trash.
const WINDOW = 'newer_than:7d in:anywhere';
const SOURCES = [
  { source: 'nik_sharma',           query: `from:niksharma@workweek.com ${WINDOW}` },
  { source: 'taylor_holiday',       query: `from:taylorholiday@commonthreadco.com ${WINDOW}` },
  { source: 'matt_bertulli',        query: `from:m@mattbertulli.com ${WINDOW}` },
  { source: 'chase_dimond',         query: `(from:chase@chasedimond.com OR from:ecomemailmarketer@mail.beehiiv.com) ${WINDOW}` },
  { source: 'operators_newsletter', query: `from:news@operatorscontent.com ${WINDOW}` },
  { source: 'jordan_west',          query: `from:jordanwestnewsletter@mail.beehiiv.com ${WINDOW}` },
  { source: 'chew_on_this',         query: `from:chew-on-this@mail.beehiiv.com ${WINDOW}` },
];
return SOURCES.map(s => ({ json: s }));

// Runs in "Run Once for All Items" mode. MUST iterate $input.all().
//
// This previously read `const msg = $json`, which in all-items mode is only the
// FIRST input item, and returned a single element. Verified against real runs:
// executions 148835 and 147883 each fetched 6 Gmail messages and POSTed exactly 1.
// Every additional newsletter that arrived the same day was silently discarded,
// and because the sync window then moved on, those issues were lost permanently.
// This was the single largest cause of the ~68% ingestion loss.
//
// Source/author are deliberately NOT resolved here: $('Source Config').first()
// always returns config item #1 regardless of which email is being handled, which
// mis-filed every issue as nik_sharma. The From header travels with the message,
// so we forward it and /ingest-newsletter derives attribution server-side.

function extractBody(part, result) {
  if (!part) return;
  if (part.body && part.body.data) {
    const decoded = Buffer.from(part.body.data, 'base64').toString('utf-8');
    if (part.mimeType === 'text/html' && !result.html) result.html = decoded;
    if (part.mimeType === 'text/plain' && !result.plain) result.plain = decoded;
  }
  for (const p of (part.parts || [])) extractBody(p, result);
}

const out = [];
for (const item of $input.all()) {
  const msg = item.json || {};
  const result = { html: '', plain: '' };
  if (msg.payload) extractBody(msg.payload, result);

  const headers = {};
  for (const h of ((msg.payload && msg.payload.headers) || msg.headers || [])) {
    if (h && h.name) headers[h.name.toLowerCase()] = h.value;
  }

  const from = headers['from'] || '';
  // Without a From header the server cannot attribute the issue. Skip rather than
  // let it fall back to whichever source happens to be first.
  if (!from) continue;

  let published = null;
  if (headers['date']) {
    const d = new Date(headers['date']);
    if (!isNaN(d.getTime())) published = d.toISOString();
  }

  out.push({ json: {
    email_id: msg.id || msg.messageId,
    source: 'unknown',            // server derives the real source from sender_email
    sender_email: from,
    subject: headers['subject'] || '',
    published_at: published,
    body_html: result.html,
    body_text: result.plain,
  }});
}
return out;
